'use client'

import type { ReactElement, ReactNode } from 'react'
import { Menu as BaseMenu } from '@base-ui/react/menu'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import styles from './Menu.module.css'

interface ItemBase {
  label: ReactNode
  /** Used for typeahead when `label` is not plain text. */
  textValue?: string
  icon?: ReactNode
  disabled?: boolean
}

/** An action, a link (`href`), or a submenu (`items`). */
export interface MenuActionItem extends ItemBase {
  type?: 'item'
  onSelect?: () => void
  href?: string
  /** Shown right-aligned, e.g. "⌘ D". Display only: it does not bind the key. */
  shortcut?: string
  /** Deletes or removes something: drawn in the danger colour. */
  isDestructive?: boolean
  /** Opens a submenu instead of acting. */
  items?: MenuEntry[]
}
export interface MenuCheckboxItem extends ItemBase {
  type: 'checkbox'
  checked?: boolean
  defaultChecked?: boolean
  onCheckedChange?: (checked: boolean) => void
}
export interface MenuRadioGroupItem {
  type: 'radio'
  label?: ReactNode
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  options: { value: string; label: ReactNode; disabled?: boolean }[]
}
export interface MenuGroupItem {
  type: 'group'
  label: ReactNode
  items: MenuEntry[]
}
export interface MenuSeparator {
  type: 'separator'
}
export type MenuEntry = MenuActionItem | MenuCheckboxItem | MenuRadioGroupItem | MenuGroupItem | MenuSeparator

export interface MenuProps {
  /** The button that opens it. Its props are merged, not wrapped. */
  trigger: ReactElement
  items: MenuEntry[]
  side?: 'top' | 'right' | 'bottom' | 'left'
  align?: 'start' | 'center' | 'end'
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /**
   * While open, lock page scroll and make the rest of the page inert, so the
   * menu is the only thing to interact with. `false` leaves the page as is.
   */
  isModal?: boolean
  /** Where the popup renders instead of `<body>`, e.g. an element in fullscreen. */
  container?: HTMLElement | null
  className?: string
}

const text = (label: ReactNode, textValue?: string) => textValue ?? (typeof label === 'string' ? label : undefined)

/** Renders `MenuEntry[]` as Base UI menu parts, inside a `MenuSurface`. A building block for menus that share Menu's look. */
export function MenuEntries({ items }: { items: MenuEntry[] }) {
  return items.map((entry, i) => {
    switch (entry.type) {
      case 'separator':
        return <BaseMenu.Separator key={i} className={styles.separator} />
      case 'group':
        return (
          <BaseMenu.Group key={i} className={styles.group}>
            <BaseMenu.GroupLabel className={styles.groupLabel}>{entry.label}</BaseMenu.GroupLabel>
            <MenuEntries items={entry.items} />
          </BaseMenu.Group>
        )
      case 'checkbox':
        return (
          <BaseMenu.CheckboxItem
            key={i}
            label={text(entry.label, entry.textValue)}
            checked={entry.checked}
            defaultChecked={entry.defaultChecked}
            onCheckedChange={entry.onCheckedChange && ((c) => entry.onCheckedChange!(c))}
            disabled={entry.disabled}
            closeOnClick={false}
            className={styles.item}
          >
            <span className={styles.indicator}>
              <BaseMenu.CheckboxItemIndicator>
                <Icon name="check" />
              </BaseMenu.CheckboxItemIndicator>
            </span>
            <span className={styles.label}>{entry.label}</span>
          </BaseMenu.CheckboxItem>
        )
      case 'radio':
        return (
          <BaseMenu.Group key={i} className={styles.group}>
            {entry.label && <BaseMenu.GroupLabel className={styles.groupLabel}>{entry.label}</BaseMenu.GroupLabel>}
            <BaseMenu.RadioGroup
              value={entry.value}
              defaultValue={entry.defaultValue}
              onValueChange={entry.onValueChange && ((v) => entry.onValueChange!(v as string))}
            >
              {entry.options.map((o) => (
                <BaseMenu.RadioItem
                  key={o.value}
                  value={o.value}
                  label={text(o.label)}
                  disabled={o.disabled}
                  closeOnClick={false}
                  className={styles.item}
                >
                  <span className={styles.indicator}>
                    <BaseMenu.RadioItemIndicator>
                      <Icon name="check" />
                    </BaseMenu.RadioItemIndicator>
                  </span>
                  <span className={styles.label}>{o.label}</span>
                </BaseMenu.RadioItem>
              ))}
            </BaseMenu.RadioGroup>
          </BaseMenu.Group>
        )
      default: {
        const content = (
          <>
            {entry.icon && (
              <span className={styles.icon} aria-hidden="true">
                {entry.icon}
              </span>
            )}
            <span className={styles.label}>{entry.label}</span>
            {entry.shortcut && (
              <kbd className={styles.shortcut} aria-hidden="true">
                {entry.shortcut}
              </kbd>
            )}
          </>
        )
        const className = cn(styles.item, entry.isDestructive && styles.destructive)
        if (entry.items) {
          return (
            <BaseMenu.SubmenuRoot key={i}>
              <BaseMenu.SubmenuTrigger label={text(entry.label, entry.textValue)} disabled={entry.disabled} className={className}>
                {content}
                <span className={styles.chevron} aria-hidden="true">
                  <Icon name="chevron-right" />
                </span>
              </BaseMenu.SubmenuTrigger>
              <MenuSurface side="right" align="start">
                <MenuEntries items={entry.items} />
              </MenuSurface>
            </BaseMenu.SubmenuRoot>
          )
        }
        // A disabled link is an inert item: Base UI's LinkItem has no disabled state.
        if (entry.href !== undefined && !entry.disabled) {
          return (
            <BaseMenu.LinkItem key={i} href={entry.href} label={text(entry.label, entry.textValue)} className={className}>
              {content}
            </BaseMenu.LinkItem>
          )
        }
        return (
          <BaseMenu.Item
            key={i}
            label={text(entry.label, entry.textValue)}
            disabled={entry.disabled}
            onClick={entry.onSelect && (() => entry.onSelect!())}
            className={className}
          >
            {content}
          </BaseMenu.Item>
        )
      }
    }
  })
}

/** Menu's popup surface, rendered through a portal, 4px from its trigger by default. */
export function MenuSurface({
  side,
  align,
  sideOffset = 4,
  container,
  className,
  children,
}: {
  side: MenuProps['side']
  align: MenuProps['align']
  sideOffset?: number
  container?: HTMLElement | null
  className?: string
  children: ReactNode
}) {
  return (
    <BaseMenu.Portal container={container}>
      <BaseMenu.Positioner className={styles.positioner} side={side} align={align} sideOffset={sideOffset}>
        <BaseMenu.Popup className={cn(styles.popup, className)}>{children}</BaseMenu.Popup>
      </BaseMenu.Positioner>
    </BaseMenu.Portal>
  )
}

export function Menu({
  trigger,
  items,
  side = 'bottom',
  align = 'start',
  open,
  defaultOpen,
  onOpenChange,
  isModal = true,
  container,
  className,
}: MenuProps) {
  return (
    <BaseMenu.Root
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange && ((next) => onOpenChange(next))}
      modal={isModal}
    >
      <BaseMenu.Trigger render={trigger} />
      <MenuSurface side={side} align={align} container={container} className={className}>
        <MenuEntries items={items} />
      </MenuSurface>
    </BaseMenu.Root>
  )
}

/* 50: the popup layer, with Select, Popover and Modal. */
.positioner {
  z-index: var(--layer-overlay);
  outline: none;
}

/* The items sit 4px inside the popup's border, as the Figma library binds
   it, so a highlighted item's corner nests inside the popup's. */
.popup {
  box-sizing: border-box;
  min-inline-size: max(12rem, var(--anchor-width));
  max-block-size: var(--available-height);
  overflow-y: auto;
  padding: var(--space-1);
  border: var(--border-width) solid var(--color-border);
  border-radius: var(--radius-lg);
  background: var(--color-surface-overlay);
  box-shadow: var(--shadow-overlay);
  color: var(--color-text);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  outline: none;
  transform-origin: var(--transform-origin);
  transition:
    opacity var(--duration-fast),
    scale var(--duration-fast);
}
.popup[data-starting-style],
.popup[data-ending-style] {
  opacity: 0;
  scale: 0.98;
}
/* Rows sit 2px apart, in the popup and inside a group. A margin, not a
   flex gap: a flex column would squeeze the rows instead of scrolling. */
.popup > * + *,
.group > * + *,
.group > [role='radiogroup'] > * + * {
  margin-block-start: var(--space-0-5);
}

/* An item follows Atlassian Design's dropdown item: 8px block and 12px
   inline padding around a 20px line, so one line is 36px, 12px between
   its parts and a 6px corner. The box ramp has no 36, so the floor is tier
   md (32px) and the padding makes the rest. */
.item {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  min-block-size: var(--control-md);
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-md);
  color: inherit;
  text-decoration: none;
  cursor: default;
  user-select: none;
  outline: none;
}

/* Highlighted: where the arrow keys or the pointer are. The submenu
   trigger keeps it while its submenu is open. */
.item[data-highlighted],
.item[data-popup-open] {
  background: var(--color-background-neutral);
  color: var(--color-text);
}

.item[data-disabled] {
  color: var(--color-text-subtlest);
  opacity: 0.6;
}

/* Text colour, not the solid: 4.5:1 on the popover and on the hover
   surface. */
.destructive {
  color: var(--color-text-danger);
}
.destructive[data-highlighted] {
  background: var(--color-background-danger);
  color: var(--color-text-danger);
}

/* 12px after the label, on top of the item's gap: a shortcut or a chevron
   sits 24px from the text, as Atlassian's. */
.label {
  flex: 1;
  padding-inline-end: var(--space-3);
}

.icon,
.indicator,
.chevron {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  inline-size: var(--icon-md);
  font-size: var(--icon-md);
}

.icon {
  color: var(--color-text-subtlest);
}
.destructive .icon {
  color: inherit;
}

.chevron {
  margin-inline-end: calc(var(--space-1) * -1);
  color: var(--color-text-subtlest);
}

.shortcut {
  font-family: inherit;
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  color: var(--color-text-subtlest);
  letter-spacing: 0.05em;
}

/* As wide as the items, 4px from the items above and below: the 2px row
   gap and the separator's own 2px in the Figma library. One margin here
   (vertical margins collapse), after the row rule above so it wins. */
.separator {
  block-size: 1px;
  margin: var(--space-1) 0;
  background: var(--color-border);
}
.separator + * {
  margin-block-start: 0;
}

/* Atlassian's group title: 8px block, 12px before, 24px after. */
.groupLabel {
  padding-block: var(--space-2);
  padding-inline: var(--space-3) var(--space-6);
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  font-weight: 600;
  color: var(--color-text-subtlest);
}

/* Items are 36px; on touch they grow to 44px. */
@media (pointer: coarse) {
  .item {
    min-block-size: var(--target-coarse);
  }
}
